// --- diagnostics -----------------------------------------------------------

std::string code_of(const cp::Status& status) { return std::string(cp::code_symbol(status.code())); }
std::string symbol_of(cp::ErrorCode code) { return std::string(cp::code_symbol(code)); }

// Records a failure - without aborting the test - when a call did not fail with
// exactly the expected code.
void check_rejected(const cp::Status& status, cp::ErrorCode expected, const std::string& context) {
  if (status.code() != expected) {
    ct::record_failure(__FILE__, __LINE__, context + ": expected " + symbol_of(expected) + " but got " +
                                                 code_of(status) + " (" + status.detail() + ")");
  }
}

template <class T>
void check_rejected(const cp::Result<T>& result, cp::ErrorCode expected, const std::string& context) {
  if (result.has_value()) {
    ct::record_failure(__FILE__, __LINE__,
                       context + ": expected " + symbol_of(expected) + " but the call succeeded");
    return;
  }
  check_rejected(result.status(), expected, context);
}

// Aborts the test when a Result carries no value; used when every later
// assertion depends on that value. Returns by value so that binding it to a
// const reference cannot outlive the temporary Result it came from.
template <class T>
T require_value(const cp::Result<T>& result, const std::string& context) {
  if (!result.has_value()) {
    CPATH_FAIL(context + ": unexpected failure " + result.status().to_string());
  }
  return result.value();
}

// --- synthetic model helpers ----------------------------------------------

cp::Node make_node(const std::string& id, const std::string& rack = std::string()) {
  cp::Node node;
  node.id = cp::NodeId{id};
  if (!rack.empty()) {
    node.placement.supplied = true;
    node.placement.site = "S0";
    node.placement.rack = rack;
    node.placement.host = id;
  }
  node.tier = cp::TierId{std::string("LEAF")};
  return node;
}

cp::Edge make_edge(const std::string& id, const std::string& from, const std::string& to) {
  cp::Edge edge;
  edge.id = cp::EdgeId{id};
  edge.from = cp::NodeId{from};
  edge.to = cp::NodeId{to};
  edge.capacity_mbps = 25000;
  edge.latency_micros = 100;
  edge.tier = cp::TierId{std::string("LEAF")};
  edge.evidence = cp::EvidenceClass::kSynthetic;
  return edge;
}

cp::FailureDomain make_domain(const std::string& id, cp::DomainKind kind, const std::string& parent) {
  cp::FailureDomain domain;
  domain.id = cp::FailureDomainId{id};
  domain.kind = kind;
  if (!parent.empty()) {
    domain.parent = cp::FailureDomainId{parent};
  }
  return domain;
}

// Two nodes joined by one edge in each direction: the smallest graph the model
// accepts. SYNTHETIC.
cp::FabricSpec two_node_fabric() {
  cp::FabricSpec spec;
  spec.topology_generation = cp::TopologyGeneration{7};
  spec.failure_domain_generation = cp::FailureDomainGeneration{3};
  spec.capacity_evidence_generation = cp::CapacityEvidenceGeneration{11};
  spec.nodes.push_back(make_node("n0"));
  spec.nodes.push_back(make_node("n1"));
  spec.edges.push_back(make_edge("e0", "n0", "n1"));
  spec.edges.push_back(make_edge("e1", "n1", "n0"));
  return spec;
}

// A ring collective declared in the given member order, so that ring rotation
// can be exercised. SYNTHETIC.
cp::CollectiveSpec ring_collective(const std::vector<std::string>& members) {
  cp::CollectiveSpec spec;
  spec.id = cp::CollectiveId{std::string("c0")};
  spec.kind = cp::CollectiveKind::kRing;
  cp::GroupSpec group;
  group.id = cp::GroupId{std::string("g0")};
  group.level = 0;
  group.pattern = cp::GroupPattern::kRing;
  for (const std::string& member : members) {
    group.members.push_back(cp::ParticipantId{member});
  }
  spec.groups.push_back(std::move(group));
  return spec;
}

std::vector<std::uint8_t> canonical_bytes(const cp::Collective& collective) {
  cp::ByteWriter writer;
  collective.encode_canonical(writer);
  return writer.bytes();
}

std::vector<std::string> edge_names(const cp::Collective& collective) {
  std::vector<std::string> names;
  names.reserve(collective.logical_edges.size());
  for (const cp::LogicalEdge& edge : collective.logical_edges) {
    names.push_back(edge.src.value() + ">" + edge.dst.value());
  }
  return names;
}

template <class T>
void shuffle(std::vector<T>& values, ct::Random& rng) {
  for (std::size_t remaining = values.size(); remaining > 1; --remaining) {
    const std::size_t other = static_cast<std::size_t>(rng.below(remaining));
    std::swap(values[remaining - 1], values[other]);
  }
}

// --- text DSL helpers ------------------------------------------------------

std::string replace_first(const std::string& text, const std::string& from, const std::string& to) {
  const std::size_t position = text.find(from);
  if (position == std::string::npos) {
    return text;
  }
  return text.substr(0, position) + to + text.substr(position + from.size());
}

// Inserts a line directly after the named section header, which is where the
// reader attributes it.
std::string insert_after_section(const std::string& text, const std::string& section, const std::string& line) {
  const std::string marker = "\n[" + section + "]\n";
  const std::size_t position = text.find(marker);
  if (position == std::string::npos) {
    return text;
  }
  return text.substr(0, position + marker.size()) + line + "\n" + text.substr(position + marker.size());
}

struct RejectionCase {
  const char* label;
  cp::ErrorCode expected;
  std::string text;
};

void check_rejection_case(const RejectionCase& item) {
  const cp::Result<cp::PlanningRequest> parsed = cp::parse_request_text(item.text);
  if (parsed.has_value()) {
    ct::record_failure(__FILE__, __LINE__, std::string(item.label) + ": expected " + symbol_of(item.expected) +
                                                 " but the request parsed successfully");
    return;
  }
  if (parsed.status().code() != item.expected) {
    ct::record_failure(__FILE__, __LINE__, std::string(item.label) + ": expected " + symbol_of(item.expected) +
                                                 " but got " + code_of(parsed.status()) + " (" +
                                                 parsed.status().detail() + ")");
  }
}

// --- plan helpers ----------------------------------------------------------

cp::GenerationBindings sample_bindings() {
  cp::GenerationBindings bindings;
  bindings.topology = cp::TopologyGeneration{7};
  bindings.failure_domains = cp::FailureDomainGeneration{3};
  bindings.capacity_evidence = cp::CapacityEvidenceGeneration{11};
  bindings.policy = cp::PolicyGeneration{5};
  bindings.plan = cp::CollectivePlanGeneration{1};
  return bindings;
}

cp::Plan plan_with_bindings(const cp::GenerationBindings& bindings) {
  cp::Plan plan;
  const cp::Digest digest = cp::Sha256::hash("synthetic-plan");
  plan.id = cp::CollectivePlanId{digest};
  plan.input_digest = digest;
  plan.generation = cp::CollectivePlanGeneration{1};
  plan.bindings = bindings;
  plan.collective = cp::CollectiveId{std::string("c0")};
  return plan;
}

// The diamond fabric used by the plan-comparison proofs: a single tree logical
// edge p0 -> p1 with two disjoint physical routes whose latency is set by the
// caller. SYNTHETIC.
cp::RequestSpec diamond_request(std::uint64_t fast_latency, std::uint64_t slow_latency) {
  cp::RequestSpec spec;
  spec.fabric.topology_generation = cp::TopologyGeneration{7};
  spec.fabric.failure_domain_generation = cp::FailureDomainGeneration{3};
  spec.fabric.capacity_evidence_generation = cp::CapacityEvidenceGeneration{11};
  spec.policy.generation = cp::PolicyGeneration{5};
  spec.plan_generation = cp::CollectivePlanGeneration{1};
  spec.fabric.failure_domains.push_back(make_domain("S0", cp::DomainKind::kSite, std::string()));
  spec.fabric.failure_domains.push_back(make_domain("R0", cp::DomainKind::kRack, "S0"));
  for (const char* id : {"n0", "a", "b", "n1"}) {
    spec.fabric.nodes.push_back(make_node(id, "R0"));
  }
  const auto route = [&spec](const std::string& id, const std::string& from, const std::string& to,
                             std::uint64_t latency) {
    cp::Edge edge = make_edge(id, from, to);
    edge.latency_micros = latency;
    edge.failure_domain = cp::FailureDomainId{std::string("R0")};
    spec.fabric.edges.push_back(std::move(edge));
  };
  route("e0", "n0", "a", fast_latency);
  route("e1", "a", "n1", fast_latency);
  route("e2", "n0", "b", slow_latency);
  route("e3", "b", "n1", slow_latency);

  spec.collective.id = cp::CollectiveId{std::string("c0")};
  spec.collective.kind = cp::CollectiveKind::kTree;
  cp::GroupSpec group;
  group.id = cp::GroupId{std::string("g0")};
  group.level = 0;
  group.pattern = cp::GroupPattern::kTree;
  group.direction = cp::TreeDirection::kForward;
  group.root = cp::ParticipantId{std::string("p0")};
  group.members.push_back(cp::ParticipantId{std::string("p0")});
  group.members.push_back(cp::ParticipantId{std::string("p1")});
  spec.collective.groups.push_back(std::move(group));

  cp::EndpointBinding source;
  source.participant = cp::ParticipantId{std::string("p0")};
  source.node = cp::NodeId{std::string("n0")};
  spec.bindings.push_back(std::move(source));
  cp::EndpointBinding target;
  target.participant = cp::ParticipantId{std::string("p1")};
  target.node = cp::NodeId{std::string("n1")};
  spec.bindings.push_back(std::move(target));
  return spec;
}

