CPATH_TEST(UnitIds, default_constructed_ids_are_invalid) {
  const cp::NodeId node{};
  CPATH_CHECK(!node.valid());
  CPATH_CHECK(!cp::NodeId{std::string()}.valid());
  CPATH_CHECK(cp::NodeId{std::string("n0")}.valid());

  const cp::LogicalEdgeId logical{};
  CPATH_CHECK(!logical.valid());
  CPATH_CHECK(!cp::LogicalEdgeId{0u}.valid());
  CPATH_CHECK(cp::LogicalEdgeId{1u}.valid());

  const cp::TopologyGeneration generation{};
  CPATH_CHECK(!generation.valid());
  CPATH_CHECK(cp::TopologyGeneration{1u}.valid());

  const cp::ParticipantId participant{};
  CPATH_CHECK(!participant.valid());
  CPATH_CHECK(!cp::EdgeId{std::string()}.valid());
  CPATH_CHECK(!cp::TierId{std::string()}.valid());
  CPATH_CHECK(!cp::FailureDomainId{std::string()}.valid());

  CPATH_CHECK_EQ(cp::to_string(cp::NodeId{std::string("n7")}), std::string("n7"));
  CPATH_CHECK_EQ(cp::to_decimal(cp::TopologyGeneration{42u}), std::string("42"));
}

CPATH_TEST(UnitIds, digest_backed_plan_id_validity) {
  const cp::CollectivePlanId empty{};
  CPATH_CHECK(!empty.valid());
  CPATH_CHECK(!cp::CollectivePlanId{cp::Digest{}}.valid());

  const cp::Digest digest = cp::Sha256::hash(std::string_view("abc"));
  const cp::CollectivePlanId plan_id{digest};
  CPATH_CHECK(plan_id.valid());
  CPATH_CHECK_EQ(cp::to_string(plan_id), digest.hex());
  CPATH_CHECK_EQ(plan_id.value().hex(),
                 std::string("ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"));
}

CPATH_TEST(UnitIds, ordering_and_hashing_are_stable) {
  std::vector<cp::NodeId> ids;
  ids.push_back(cp::NodeId{std::string("nc")});
  ids.push_back(cp::NodeId{std::string("na")});
  ids.push_back(cp::NodeId{std::string("nb")});
  std::sort(ids.begin(), ids.end());
  CPATH_CHECK_EQ(ids[0].value(), std::string("na"));
  CPATH_CHECK_EQ(ids[1].value(), std::string("nb"));
  CPATH_CHECK_EQ(ids[2].value(), std::string("nc"));
  CPATH_CHECK(ids[0] < ids[1]);
  CPATH_CHECK(ids[1] < ids[2]);
  CPATH_CHECK(!(ids[0] < ids[0]));

  const cp::NodeId copy = ids[1];
  CPATH_CHECK(copy == ids[1]);
  // Equal identities hash equally, and the hash only depends on the value.
  const cp::StrongIdHash<cp::NodeIdTag, std::string> node_hasher;
  CPATH_CHECK_EQ(node_hasher(copy), node_hasher(ids[1]));
  CPATH_CHECK_EQ(node_hasher(ids[1]), std::hash<std::string>{}(std::string("nb")));

  const cp::Digest digest = cp::Sha256::hash(std::string_view("abc"));
  const cp::CollectivePlanId first{digest};
  const cp::CollectivePlanId second{cp::Sha256::hash(std::string_view("abc"))};
  CPATH_CHECK(first == second);
  const cp::StrongIdHash<cp::CollectivePlanIdTag, cp::Digest> plan_hasher;
  CPATH_CHECK_EQ(plan_hasher(first), cp::DigestHash{}(digest));
}

CPATH_TEST(UnitIds, id_map_matches_equal_identities) {
  cp::IdMap<cp::NodeId> map;
  map.emplace(cp::NodeId{std::string("n0")}, 0u);
  map.emplace(cp::NodeId{std::string("n1")}, 1u);
  map.emplace(cp::NodeId{std::string("n2")}, 2u);

  const auto found = map.find(cp::NodeId{std::string("n1")});
  CPATH_REQUIRE(found != map.end());
  CPATH_CHECK_EQ(found->second, std::uint32_t{1});
  CPATH_CHECK(map.find(cp::NodeId{std::string("n9")}) == map.end());
  // An invalid sentinel never aliases a stored identity.
  CPATH_CHECK(map.find(cp::NodeId{}) == map.end());
}

// ===========================================================================
// Canonical byte encoding
// ===========================================================================

CPATH_TEST(UnitBuffer, identical_values_encode_identically) {
  const cp::Digest digest = cp::Sha256::hash(std::string_view("payload"));
  cp::ByteWriter first;
  cp::ByteWriter second;
  for (cp::ByteWriter* writer : {&first, &second}) {
    writer->u8(0xABu);
    writer->u16(0x1234u);
    writer->u32(0x12345678u);
    writer->u64(0x0123456789ABCDEFull);
    writer->boolean(true);
    writer->boolean(false);
    writer->string(std::string_view("collective"));
    writer->digest(digest);
    writer->tagged(std::string_view("fabric.v1"));
  }
  CPATH_CHECK_EQ(first.size(), second.size());
  CPATH_CHECK(first.bytes() == second.bytes());
  CPATH_CHECK_EQ(first.sha256().hex(), second.sha256().hex());

  cp::ByteWriter different;
  different.u8(0xABu);
  CPATH_CHECK(!(different.bytes() == first.bytes()));
  CPATH_CHECK(different.sha256() != first.sha256());
  CPATH_CHECK(first.bytes().size() == first.size());
}

CPATH_TEST(UnitBuffer, integers_are_little_endian) {
  cp::ByteWriter writer;
  writer.u16(0x0102u);
  writer.u32(0x03040506u);
  writer.u64(0x0708090A0B0C0D0Eu);
  const std::vector<std::uint8_t> expected = {0x02u, 0x01u,                              // u16
                                              0x06u, 0x05u, 0x04u, 0x03u,                // u32
                                              0x0Eu, 0x0Du, 0x0Cu, 0x0Bu, 0x0Au, 0x09u, 0x08u, 0x07u};
  CPATH_CHECK(writer.bytes() == expected);

  cp::ByteReader reader(writer.bytes());
  std::uint16_t short_value = 0;
  std::uint32_t word = 0;
  std::uint64_t wide = 0;
  CPATH_REQUIRE(reader.u16(short_value).is_ok());
  CPATH_REQUIRE(reader.u32(word).is_ok());
  CPATH_REQUIRE(reader.u64(wide).is_ok());
  CPATH_CHECK_EQ(short_value, std::uint16_t{0x0102u});
  CPATH_CHECK_EQ(word, std::uint32_t{0x03040506u});
  CPATH_CHECK_EQ(wide, std::uint64_t{0x0708090A0B0C0D0Eu});
  CPATH_CHECK(reader.require_end().is_ok());
  CPATH_CHECK(reader.at_end());
  CPATH_CHECK_EQ(reader.remaining(), std::size_t{0});
}

CPATH_TEST(UnitBuffer, count_rejects_over_large_counts) {
  cp::ByteWriter writer;
  writer.u32(11u);
  const std::vector<std::uint8_t> bytes = writer.bytes();

  cp::ByteReader rejected(bytes);
  std::uint32_t value = 0;
  check_rejected(rejected.count(value, 10u), cp::ErrorCode::kTooManyItems, "count above the accepted bound");

  cp::ByteReader accepted(bytes);
  CPATH_REQUIRE(accepted.count(value, 11u).is_ok());
  CPATH_CHECK_EQ(value, std::uint32_t{11u});

  cp::ByteReader generous(bytes);
  CPATH_REQUIRE(generous.count(value, 4096u).is_ok());
  CPATH_CHECK_EQ(value, std::uint32_t{11u});
  CPATH_CHECK(generous.at_end());
}

CPATH_TEST(UnitBuffer, string_rejects_over_long_strings) {
  const std::string oversized(cp::kMaxIdentifierBytes + 1u, 'x');
  cp::ByteWriter writer;
  writer.string(oversized);
  const std::vector<std::uint8_t> bytes = writer.bytes();

  cp::ByteReader rejected(bytes);
  std::string value;
  check_rejected(rejected.string(value), cp::ErrorCode::kStringTooLong, "string above the default bound");

  cp::ByteReader accepted(bytes);
  CPATH_REQUIRE(accepted.string(value, oversized.size()).is_ok());
  CPATH_CHECK_EQ(value, oversized);

  cp::ByteReader exact(bytes);
  CPATH_REQUIRE(exact.string(value, cp::kMaxIdentifierBytes + 1u).is_ok());
  CPATH_CHECK_EQ(value.size(), oversized.size());
}

CPATH_TEST(UnitBuffer, require_end_rejects_trailing_bytes) {
  cp::ByteWriter writer;
  writer.u8(1u);
  writer.u8(2u);
  const std::vector<std::uint8_t> bytes = writer.bytes();

  cp::ByteReader reader(bytes);
  std::uint8_t value = 0;
  CPATH_REQUIRE(reader.u8(value).is_ok());
  CPATH_CHECK(!reader.at_end());
  check_rejected(reader.require_end(), cp::ErrorCode::kTrailingGarbage, "trailing byte");

  cp::ByteReader exact(bytes);
  std::span<const std::uint8_t> view;
  CPATH_REQUIRE(exact.raw(bytes.size(), view).is_ok());
  CPATH_CHECK(exact.require_end().is_ok());
}

CPATH_TEST(UnitBuffer, read_failure_poisons_later_reads) {
  cp::ByteReader empty(nullptr, 0u);
  std::uint8_t byte = 0;
  const cp::Status first = empty.u8(byte);
  CPATH_CHECK_EQ(code_of(first), symbol_of(cp::ErrorCode::kTruncatedRecord));

  std::uint64_t wide = 0;
  std::string text;
  cp::Digest digest;
  const cp::Status second = empty.u64(wide);
  const cp::Status third = empty.string(text);
  const cp::Status fourth = empty.digest(digest);
  // Every later read reports exactly the first failure, never a different one.
  CPATH_CHECK(second == first);
  CPATH_CHECK(third == first);
  CPATH_CHECK(fourth == first);
  // require_end() would otherwise succeed here (the reader is at its end); a
  // poisoned reader must still report the original failure.
  CPATH_CHECK(empty.at_end());
  CPATH_CHECK(empty.require_end() == first);
  CPATH_CHECK(empty.status() == first);

  cp::ByteReader sized(reinterpret_cast<const std::uint8_t*>("ab"), 2u);
  std::string captured;
  const cp::Status truncation = sized.string(captured);
  CPATH_CHECK_EQ(code_of(truncation), symbol_of(cp::ErrorCode::kTruncatedRecord));
  std::uint32_t word = 0;
  CPATH_CHECK(sized.u32(word) == truncation);
}

CPATH_TEST(UnitBuffer, checked_helpers_never_truncate) {
  CPATH_CHECK(cp::fits_u32(0u));
  CPATH_CHECK(cp::fits_u32(0xFFFFFFFFu));
  CPATH_CHECK(!cp::fits_u32(0x100000000ull));

  std::uint64_t out = 0;
  CPATH_CHECK(cp::checked_add_u64(1u, 2u, cp::kCostCeiling, out).is_ok());
  CPATH_CHECK_EQ(out, std::uint64_t{3u});
  const cp::Status overflow = cp::checked_add_u64(cp::kCostCeiling, 1u, cp::kCostCeiling, out);
  CPATH_CHECK_EQ(code_of(overflow), symbol_of(cp::ErrorCode::kOverflow));
  CPATH_CHECK_EQ(out, cp::kCostCeiling);
}

// ===========================================================================
// Digests and saturating arithmetic
// ===========================================================================

CPATH_TEST(UnitDigest, sha256_matches_published_vectors) {
  CPATH_CHECK_EQ(cp::Sha256::hash(std::string_view()).hex(),
                 std::string("e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"));
  CPATH_CHECK_EQ(cp::Sha256::hash(std::string_view("abc")).hex(),
                 std::string("ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"));
  // 56 bytes: crosses the padding boundary of a single block.
  CPATH_CHECK_EQ(cp::Sha256::hash(std::string_view("abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq")).hex(),
                 std::string("248d6a61d20638b8e5c026930c3e6039a33ce45964ff2167f6ecedd419db06c1"));
  CPATH_CHECK(cp::Sha256::hash(std::string_view("abc")).is_zero() == false);
  CPATH_CHECK(cp::Digest{}.is_zero());
}

CPATH_TEST(UnitDigest, sha256_incremental_matches_one_shot) {
  cp::Sha256 hasher;
  hasher.update(std::string_view("a"));
  hasher.update(std::string_view("b"));
  hasher.update(std::string_view("c"));
  CPATH_CHECK_EQ(hasher.finish().hex(), cp::Sha256::hash(std::string_view("abc")).hex());

  // A long input split at an awkward boundary must still hash identically.
  std::string payload;
  for (int index = 0; index < 200; ++index) {
    payload += "collective-path-planner/";
  }
  cp::Sha256 incremental;
  const std::size_t split = 63u;
  incremental.update(std::string_view(payload).substr(0, split));
  incremental.update(std::string_view(payload).substr(split));
  CPATH_CHECK_EQ(incremental.finish().hex(), cp::Sha256::hash(std::string_view(payload)).hex());
  CPATH_CHECK(payload.size() > 64u);
}

CPATH_TEST(UnitDigest, crc32_and_fnv1a64_known_values) {
  const std::string_view check = "123456789";
  CPATH_CHECK_EQ(cp::crc32(reinterpret_cast<const std::uint8_t*>(check.data()), check.size()),
                 std::uint32_t{0xCBF43926u});
  CPATH_CHECK_EQ(cp::crc32(nullptr, 0u), std::uint32_t{0u});
  CPATH_CHECK_EQ(cp::fnv1a64(std::string_view()), std::uint64_t{0xCBF29CE484222325ull});
  CPATH_CHECK_EQ(cp::fnv1a64(std::string_view("a")), std::uint64_t{0xAF63DC4C8601EC8Cull});
  CPATH_CHECK(cp::fnv1a64(std::string_view("abc")) != cp::fnv1a64(std::string_view("abd")));
}

CPATH_TEST(UnitDigest, from_hex_round_trips_and_rejects_bad_input) {
  const cp::Digest digest = cp::Sha256::hash(std::string_view("abc"));
  const std::string text = digest.hex();
  CPATH_CHECK_EQ(text.size(), std::size_t{64});
  const cp::Digest decoded = require_value(cp::Digest::from_hex(text), "digest round trip");
  CPATH_CHECK(decoded == digest);
  CPATH_CHECK_EQ(decoded.hex(), text);
  CPATH_CHECK_EQ(cp::Digest::from_hex(text).value().short_id(), digest.short_id());

  // Documented decision: hexadecimal input is case-insensitive on decode, the
  // canonical rendering is always lower case.
  std::string upper = text;
  for (char& ch : upper) {
    if (ch >= 'a' && ch <= 'f') {
      ch = static_cast<char>(ch - 'a' + 'A');
    }
  }
  CPATH_CHECK(upper != text);
  CPATH_CHECK(require_value(cp::Digest::from_hex(upper), "upper case digest") == digest);

  check_rejected(cp::Digest::from_hex(text.substr(0, 63)), cp::ErrorCode::kInvalidSyntax, "63 hex characters");
  check_rejected(cp::Digest::from_hex(text + "0"), cp::ErrorCode::kInvalidSyntax, "65 hex characters");
  check_rejected(cp::Digest::from_hex(std::string_view()), cp::ErrorCode::kInvalidSyntax, "empty digest text");
  check_rejected(cp::Digest::from_hex(replace_first(text, "b", "z")), cp::ErrorCode::kInvalidCharacter,
                 "non hex character");
  check_rejected(cp::Digest::from_hex("0x" + text.substr(2)), cp::ErrorCode::kInvalidCharacter, "0x prefix");
}

CPATH_TEST(UnitDigest, saturating_helpers_never_wrap) {
  CPATH_CHECK_EQ(cp::saturating_add(5u, 3u, 10u), std::uint64_t{8u});
  CPATH_CHECK_EQ(cp::saturating_add(9u, 9u, 10u), std::uint64_t{10u});
  CPATH_CHECK_EQ(cp::saturating_add(10u, 0u, 10u), std::uint64_t{10u});
  CPATH_CHECK_EQ(cp::saturating_add(0u, 10u, 10u), std::uint64_t{10u});
  CPATH_CHECK_EQ(cp::saturating_mul(0u, 7u, 10u), std::uint64_t{0u});
  CPATH_CHECK_EQ(cp::saturating_mul(3u, 4u, 100u), std::uint64_t{12u});
  CPATH_CHECK_EQ(cp::saturating_mul(3u, 4u, 10u), std::uint64_t{10u});
  CPATH_CHECK_EQ(cp::saturating_mul(10u, 10u, 10u), std::uint64_t{10u});
  CPATH_CHECK_EQ(cp::saturating_sub(9u, 4u), std::uint64_t{5u});
  CPATH_CHECK_EQ(cp::saturating_sub(4u, 9u), std::uint64_t{0u});
  CPATH_CHECK_EQ(cp::saturating_sub(0u, 0u), std::uint64_t{0u});

  // Property: over the whole plausible scoring range the results saturate
  // exactly at the ceiling and never wrap around it.
  ct::Random rng = ct::make_random(1);
  for (int iteration = 0; iteration < 2000; ++iteration) {
    const std::uint64_t lhs = rng.below(cp::kCostCeiling);
    const std::uint64_t rhs = rng.below(cp::kCostCeiling);

    const std::uint64_t sum = cp::saturating_add(lhs, rhs, cp::kCostCeiling);
    CPATH_CHECK(sum <= cp::kCostCeiling);
    CPATH_CHECK(sum >= lhs);
    CPATH_CHECK(sum >= rhs);
    if (lhs <= cp::kCostCeiling - rhs) {
      CPATH_CHECK_EQ(sum, lhs + rhs);
    } else {
      CPATH_CHECK_EQ(sum, cp::kCostCeiling);
    }

    const std::uint64_t product = cp::saturating_mul(lhs, rhs, cp::kCostCeiling);
    CPATH_CHECK(product <= cp::kCostCeiling);
    if (lhs == 0u || rhs == 0u) {
      CPATH_CHECK_EQ(product, std::uint64_t{0u});
    } else if (lhs <= cp::kCostCeiling / rhs) {
      CPATH_CHECK_EQ(product, lhs * rhs);
    } else {
      CPATH_CHECK_EQ(product, cp::kCostCeiling);
    }

    CPATH_CHECK_EQ(cp::saturating_sub(lhs, rhs), lhs > rhs ? lhs - rhs : 0u);
  }
}

