CPATH_TEST(UnitCollective, ring_rotation_is_canonical) {
  const cp::Collective& from_zero = require_value(cp::Collective::build(ring_collective({"p0", "p1", "p2", "p3"})),
                                                 "ring starting at p0");
  const cp::Collective& from_two = require_value(cp::Collective::build(ring_collective({"p2", "p3", "p0", "p1"})),
                                                "ring starting at p2");
  // Entering the same cycle at a different member is the same collective.
  CPATH_CHECK(canonical_bytes(from_zero) == canonical_bytes(from_two));
  CPATH_CHECK(edge_names(from_zero) == edge_names(from_two));
  CPATH_REQUIRE_EQ(from_two.groups.size(), std::size_t{1});
  CPATH_CHECK_EQ(from_two.groups[0].members[0].value(), std::string("p0"));
  CPATH_CHECK_EQ(from_two.groups[0].members[3].value(), std::string("p3"));

  const std::vector<std::string> expected = {"p0>p1", "p1>p2", "p2>p3", "p3>p0"};
  CPATH_CHECK(edge_names(from_zero) == expected);
  CPATH_CHECK(from_zero.validate().is_ok());
  CPATH_REQUIRE_EQ(from_zero.stage_count, std::uint32_t{1});
  CPATH_CHECK(from_zero.logical_edge_id(0) == cp::LogicalEdgeId{1u});
  CPATH_CHECK(from_zero.logical_edge_id(3) == cp::LogicalEdgeId{4u});
}

CPATH_TEST(UnitCollective, ring_reversal_changes_the_encoding) {
  const cp::Collective& forward = require_value(cp::Collective::build(ring_collective({"p0", "p1", "p2", "p3"})),
                                                "forward ring");
  const cp::Collective& reverse = require_value(cp::Collective::build(ring_collective({"p0", "p3", "p2", "p1"})),
                                                "reversed ring");
  CPATH_CHECK(!(canonical_bytes(forward) == canonical_bytes(reverse)));
  // Reversal changes the direction of every logical edge.
  const std::vector<std::string> expected = {"p0>p3", "p1>p0", "p2>p1", "p3>p2"};
  CPATH_CHECK(edge_names(reverse) == expected);
  CPATH_CHECK(edge_names(forward) != edge_names(reverse));
  CPATH_CHECK_EQ(reverse.participants.size(), std::size_t{4});
}

CPATH_TEST(UnitCollective, tree_directions_produce_the_declared_edge_sets) {
  const auto tree = [](cp::TreeDirection direction) {
    cp::CollectiveSpec spec;
    spec.id = cp::CollectiveId{std::string("t0")};
    spec.kind = cp::CollectiveKind::kTree;
    cp::GroupSpec group;
    group.id = cp::GroupId{std::string("g0")};
    group.level = 0;
    group.pattern = cp::GroupPattern::kTree;
    group.direction = direction;
    group.root = cp::ParticipantId{std::string("p0")};
    group.members.push_back(cp::ParticipantId{std::string("p2")});
    group.members.push_back(cp::ParticipantId{std::string("p0")});
    group.members.push_back(cp::ParticipantId{std::string("p1")});
    spec.groups.push_back(std::move(group));
    return spec;
  };

  const cp::Collective& forward =
      require_value(cp::Collective::build(tree(cp::TreeDirection::kForward)), "forward tree");
  CPATH_CHECK(edge_names(forward) == std::vector<std::string>({"p0>p1", "p0>p2"}));

  const cp::Collective& reverse =
      require_value(cp::Collective::build(tree(cp::TreeDirection::kReverse)), "reverse tree");
  CPATH_CHECK(edge_names(reverse) == std::vector<std::string>({"p1>p0", "p2>p0"}));

  const cp::Collective& both =
      require_value(cp::Collective::build(tree(cp::TreeDirection::kBidirectional)), "bidirectional tree");
  CPATH_CHECK(edge_names(both) == std::vector<std::string>({"p0>p1", "p0>p2", "p1>p0", "p2>p0"}));

  cp::CollectiveSpec missing_root = tree(cp::TreeDirection::kForward);
  missing_root.groups[0].root = cp::ParticipantId{};
  check_rejected(cp::Collective::build(missing_root), cp::ErrorCode::kMissingRequiredField, "tree without a root");

  cp::CollectiveSpec foreign_root = tree(cp::TreeDirection::kForward);
  foreign_root.groups[0].root = cp::ParticipantId{std::string("p9")};
  check_rejected(cp::Collective::build(foreign_root), cp::ErrorCode::kUnknownReference,
                 "tree root outside the member set");
}

CPATH_TEST(UnitCollective, pairwise_requires_an_even_member_count) {
  cp::CollectiveSpec odd;
  odd.id = cp::CollectiveId{std::string("w0")};
  odd.kind = cp::CollectiveKind::kPairwise;
  cp::GroupSpec group;
  group.id = cp::GroupId{std::string("g0")};
  group.pattern = cp::GroupPattern::kPairwise;
  for (const char* member : {"p0", "p1", "p2"}) {
    group.members.push_back(cp::ParticipantId{member});
  }
  odd.groups.push_back(group);
  check_rejected(cp::Collective::build(odd), cp::ErrorCode::kInconsistentMetadata, "odd pairwise group");

  cp::CollectiveSpec even = odd;
  even.groups[0].members.push_back(cp::ParticipantId{std::string("p3")});
  const cp::Collective& built = require_value(cp::Collective::build(even), "even pairwise group");
  CPATH_CHECK(edge_names(built) == std::vector<std::string>({"p0>p1", "p1>p0", "p2>p3", "p3>p2"}));
  CPATH_CHECK_EQ(built.stage_count, std::uint32_t{1});
}

CPATH_TEST(UnitCollective, all_to_all_produces_ordered_pairs) {
  cp::CollectiveSpec spec;
  spec.id = cp::CollectiveId{std::string("a0")};
  spec.kind = cp::CollectiveKind::kAllToAll;
  cp::GroupSpec group;
  group.id = cp::GroupId{std::string("g0")};
  group.pattern = cp::GroupPattern::kAllToAll;
  for (const char* member : {"p3", "p1", "p0", "p2"}) {
    group.members.push_back(cp::ParticipantId{member});
  }
  spec.groups.push_back(group);

  const cp::Collective& built = require_value(cp::Collective::build(spec), "all to all");
  CPATH_CHECK_EQ(built.logical_edges.size(), std::size_t{12});
  CPATH_CHECK_EQ(built.participants.size(), std::size_t{4});
  CPATH_CHECK_EQ(built.logical_edges.size(), built.participants.size() * (built.participants.size() - 1u));
  // Members were declared out of order; the canonical list is sorted.
  CPATH_CHECK_EQ(built.groups[0].members[0].value(), std::string("p0"));
  const std::vector<std::string> names = edge_names(built);
  for (const std::string& name : names) {
    const std::size_t separator = name.find('>');
    CPATH_REQUIRE(separator != std::string::npos);
    CPATH_CHECK(name.substr(0, separator) != name.substr(separator + 1u));
  }
  cp::LogicalEdge probe;
  probe.src = cp::ParticipantId{std::string("p0")};
  probe.dst = cp::ParticipantId{std::string("p3")};
  CPATH_CHECK(std::find(built.logical_edges.begin(), built.logical_edges.end(), probe) != built.logical_edges.end());
}

CPATH_TEST(UnitCollective, hierarchy_levels_become_stages) {
  cp::CollectiveSpec spec;
  spec.id = cp::CollectiveId{std::string("h0")};
  spec.kind = cp::CollectiveKind::kHierarchical;
  cp::GroupSpec inner;
  inner.id = cp::GroupId{std::string("g-inner")};
  inner.level = 0;
  inner.pattern = cp::GroupPattern::kRing;
  inner.members.push_back(cp::ParticipantId{std::string("p1")});
  inner.members.push_back(cp::ParticipantId{std::string("p0")});
  cp::GroupSpec outer;
  outer.id = cp::GroupId{std::string("g-outer")};
  outer.level = 1;
  outer.pattern = cp::GroupPattern::kRing;
  outer.members.push_back(cp::ParticipantId{std::string("p2")});
  outer.members.push_back(cp::ParticipantId{std::string("p3")});
  spec.groups.push_back(outer);
  spec.groups.push_back(inner);

  const cp::Collective& built = require_value(cp::Collective::build(spec), "hierarchy");
  CPATH_CHECK_EQ(built.stage_count, std::uint32_t{2});
  CPATH_REQUIRE_EQ(built.logical_edges.size(), std::size_t{4});
  CPATH_REQUIRE_EQ(built.logical_edge_stage.size(), built.logical_edges.size());
  // Groups are canonicalised by (level, id).
  CPATH_CHECK_EQ(built.groups[0].id.value(), std::string("g-inner"));
  CPATH_CHECK_EQ(built.groups[1].id.value(), std::string("g-outer"));
  for (std::size_t index = 0; index < built.logical_edges.size(); ++index) {
    const std::string& src = built.logical_edges[index].src.value();
    const std::uint32_t expected = (src == "p0" || src == "p1") ? 0u : 1u;
    CPATH_CHECK_EQ(built.logical_edge_stage[index], expected);
  }

  // The same logical edge implied by two levels is attributed to the earliest
  // stage and is still one exchange.
  cp::CollectiveSpec shared = spec;
  cp::GroupSpec duplicate;
  duplicate.id = cp::GroupId{std::string("g-dup")};
  duplicate.level = 1;
  duplicate.pattern = cp::GroupPattern::kRing;
  duplicate.members.push_back(cp::ParticipantId{std::string("p0")});
  duplicate.members.push_back(cp::ParticipantId{std::string("p1")});
  shared.groups.push_back(duplicate);
  const cp::Collective& merged = require_value(cp::Collective::build(shared), "shared logical edge");
  CPATH_CHECK_EQ(merged.logical_edges.size(), std::size_t{4});
  for (std::size_t index = 0; index < merged.logical_edges.size(); ++index) {
    if (merged.logical_edges[index].src.value() == "p0" || merged.logical_edges[index].src.value() == "p1") {
      CPATH_CHECK_EQ(merged.logical_edge_stage[index], std::uint32_t{0});
    }
  }
}

CPATH_TEST(UnitCollective, duplicate_members_are_rejected) {
  check_rejected(cp::Collective::build(ring_collective({"p0", "p1", "p0"})), cp::ErrorCode::kDuplicateIdentifier,
                 "ring repeating a member");

  cp::CollectiveSpec pairwise;
  pairwise.id = cp::CollectiveId{std::string("w0")};
  cp::GroupSpec group;
  group.id = cp::GroupId{std::string("g0")};
  group.pattern = cp::GroupPattern::kPairwise;
  group.members.push_back(cp::ParticipantId{std::string("p0")});
  group.members.push_back(cp::ParticipantId{std::string("p0")});
  pairwise.groups.push_back(group);
  check_rejected(cp::Collective::build(pairwise), cp::ErrorCode::kDuplicateIdentifier,
                 "pairwise repeating a member");

  cp::CollectiveSpec no_groups;
  no_groups.id = cp::CollectiveId{std::string("c0")};
  check_rejected(cp::Collective::build(no_groups), cp::ErrorCode::kEmptyCollective, "collective without groups");
}

CPATH_TEST(UnitCollective, self_loop_logical_edge_is_rejected) {
  // A self loop cannot be derived from a group (duplicate members are refused
  // first), so the structural guard is proved directly on the model.
  cp::Collective collective;
  collective.id = cp::CollectiveId{std::string("c0")};
  collective.kind = cp::CollectiveKind::kRing;
  collective.participants.push_back(cp::ParticipantId{std::string("p0")});
  collective.logical_edges.push_back(
      cp::LogicalEdge{cp::ParticipantId{std::string("p0")}, cp::ParticipantId{std::string("p0")}});
  collective.logical_edge_stage.push_back(0u);
  collective.stage_count = 1;
  check_rejected(collective.validate(), cp::ErrorCode::kSelfLoopLogicalEdge, "self loop logical edge");

  const cp::Collective& valid =
      require_value(cp::Collective::build(ring_collective({"p0", "p1"})), "two member ring");
  CPATH_CHECK(valid.validate().is_ok());
  CPATH_CHECK_EQ(valid.logical_edges.size(), std::size_t{2});
}

