CPATH_TEST(UnitPolicy, validate_rejects_out_of_range_limits) {
  cp::Policy policy;
  policy.generation = cp::PolicyGeneration{1};
  CPATH_CHECK(policy.validate().is_ok());

  policy.max_hops = 0;
  check_rejected(policy.validate(), cp::ErrorCode::kValueOutOfRange, "max-hops of zero");
  policy.max_hops = cp::kMaxHops + 1u;
  check_rejected(policy.validate(), cp::ErrorCode::kValueOutOfRange, "max-hops above the model bound");
  policy.max_hops = cp::kMaxHops;
  CPATH_CHECK(policy.validate().is_ok());

  policy.paths_per_logical_edge = 0;
  check_rejected(policy.validate(), cp::ErrorCode::kPathCountUnsupported, "zero paths per logical edge");
  policy.paths_per_logical_edge = cp::kMaxPathsPerLogicalEdge + 1u;
  check_rejected(policy.validate(), cp::ErrorCode::kPathCountUnsupported, "too many paths per logical edge");
  policy.paths_per_logical_edge = cp::kMaxPathsPerLogicalEdge;
  CPATH_CHECK(policy.validate().is_ok());
  policy.paths_per_logical_edge = cp::kMinPathsPerLogicalEdge;

  policy.generation = cp::PolicyGeneration{};
  check_rejected(policy.validate(), cp::ErrorCode::kMissingRequiredField, "policy without a generation");
  policy.generation = cp::PolicyGeneration{1};

  policy.max_search_expansions = 0;
  check_rejected(policy.validate(), cp::ErrorCode::kValueOutOfRange, "empty search budget");
  policy.max_search_expansions = cp::kMaxSearchExpansions + 1u;
  check_rejected(policy.validate(), cp::ErrorCode::kValueOutOfRange, "search budget above the model bound");
  policy.max_search_expansions = 1u << 18;

  policy.max_path_cost = 0;
  check_rejected(policy.validate(), cp::ErrorCode::kValueOutOfRange, "zero cost limit");
  policy.max_path_cost = cp::kCostCeiling;
  policy.latency_weight_milli = cp::kMaxScoringWeightMilli + 1u;
  check_rejected(policy.validate(), cp::ErrorCode::kValueOutOfRange, "scoring weight above the model bound");
}

CPATH_TEST(UnitPolicy, validate_rejects_a_tier_that_is_allowed_and_forbidden) {
  cp::Policy policy;
  policy.generation = cp::PolicyGeneration{1};
  policy.forbidden_tiers.push_back(cp::TierId{std::string("T1")});
  policy.allowed_path_tiers.push_back(cp::TierId{std::string("T1")});
  check_rejected(policy.validate(), cp::ErrorCode::kInconsistentMetadata, "tier both allowed and forbidden");

  policy.allowed_path_tiers.clear();
  policy.allowed_path_tiers.push_back(cp::TierId{std::string("T2")});
  CPATH_CHECK(policy.validate().is_ok());

  policy.forbidden_nodes.push_back(cp::NodeId{std::string("bad node")});
  check_rejected(policy.validate(), cp::ErrorCode::kInvalidCharacter, "forbidden node with a space");
}

CPATH_TEST(UnitPolicy, canonicalize_sorts_and_deduplicates_sets) {
  cp::Policy policy;
  policy.generation = cp::PolicyGeneration{1};
  policy.forbidden_nodes.push_back(cp::NodeId{std::string("n2")});
  policy.forbidden_nodes.push_back(cp::NodeId{std::string("n1")});
  policy.forbidden_nodes.push_back(cp::NodeId{std::string("n2")});
  policy.forbidden_tiers.push_back(cp::TierId{std::string("T2")});
  policy.forbidden_tiers.push_back(cp::TierId{std::string("T1")});
  policy.forbidden_tiers.push_back(cp::TierId{std::string("T1")});
  policy.forbidden_failure_domains.push_back(cp::FailureDomainId{std::string("F2")});
  policy.forbidden_failure_domains.push_back(cp::FailureDomainId{std::string("F1")});
  policy.forbidden_failure_domains.push_back(cp::FailureDomainId{std::string("F1")});
  policy.allowed_path_tiers.push_back(cp::TierId{std::string("T9")});
  policy.allowed_path_tiers.push_back(cp::TierId{std::string("T8")});
  policy.allowed_path_tiers.push_back(cp::TierId{std::string("T9")});

  // A set-valued field is rejected until it is canonicalised, which proves the
  // canonicalisation below is doing real work.
  check_rejected(policy.validate(), cp::ErrorCode::kInconsistentMetadata, "unsorted policy sets");

  policy.canonicalize();
  CPATH_REQUIRE_EQ(policy.forbidden_nodes.size(), std::size_t{2});
  CPATH_CHECK_EQ(policy.forbidden_nodes[0].value(), std::string("n1"));
  CPATH_CHECK_EQ(policy.forbidden_nodes[1].value(), std::string("n2"));
  CPATH_REQUIRE_EQ(policy.forbidden_tiers.size(), std::size_t{2});
  CPATH_CHECK_EQ(policy.forbidden_tiers[0].value(), std::string("T1"));
  CPATH_REQUIRE_EQ(policy.forbidden_failure_domains.size(), std::size_t{2});
  CPATH_CHECK_EQ(policy.forbidden_failure_domains[0].value(), std::string("F1"));
  CPATH_REQUIRE_EQ(policy.allowed_path_tiers.size(), std::size_t{2});
  CPATH_CHECK_EQ(policy.allowed_path_tiers[0].value(), std::string("T8"));
  CPATH_CHECK(policy.validate().is_ok());
}

// ===========================================================================
// Request construction
// ===========================================================================

CPATH_TEST(UnitRequest, declaration_order_does_not_change_the_digest) {
  ct::SyntheticParams params;
  params.participants = 6;
  params.spine_count = 2;
  params.rack_count = 3;
  const cp::RequestSpec ordered = ct::make_ring_spec(params);  // SYNTHETIC fabric

  const cp::PlanningRequest& first = require_value(cp::build_request(ordered), "ordered request");

  // A deterministic reversal proves the declaration order really moved.
  cp::RequestSpec reversed = ordered;
  std::reverse(reversed.fabric.failure_domains.begin(), reversed.fabric.failure_domains.end());
  std::reverse(reversed.fabric.nodes.begin(), reversed.fabric.nodes.end());
  std::reverse(reversed.fabric.edges.begin(), reversed.fabric.edges.end());
  std::reverse(reversed.bindings.begin(), reversed.bindings.end());
  std::reverse(reversed.collective.groups.begin(), reversed.collective.groups.end());
  CPATH_REQUIRE(reversed.fabric.nodes.size() > 1u);
  CPATH_CHECK(reversed.fabric.nodes[0].id.value() != ordered.fabric.nodes[0].id.value());
  CPATH_CHECK(reversed.fabric.edges[0].id.value() != ordered.fabric.edges[0].id.value());

  const cp::PlanningRequest& second = require_value(cp::build_request(reversed), "reversed request");
  CPATH_CHECK_EQ(first.canonical_digest.hex(), second.canonical_digest.hex());
  CPATH_CHECK_EQ(first.canonical_bytes, second.canonical_bytes);
  cp::ByteWriter rebuilt;
  second.encode_canonical(rebuilt);
  CPATH_CHECK_EQ(rebuilt.size(), second.canonical_bytes);
  CPATH_CHECK_EQ(rebuilt.sha256().hex(), first.canonical_digest.hex());

  // A seeded shuffle of the same declarations is equivalent as well.
  cp::RequestSpec shuffled = ordered;
  ct::Random rng = ct::make_random(11);
  shuffle(shuffled.fabric.failure_domains, rng);
  shuffle(shuffled.fabric.nodes, rng);
  shuffle(shuffled.fabric.edges, rng);
  shuffle(shuffled.bindings, rng);
  shuffle(shuffled.collective.groups, rng);
  const cp::PlanningRequest& third = require_value(cp::build_request(shuffled), "shuffled request");
  CPATH_CHECK_EQ(first.canonical_digest.hex(), third.canonical_digest.hex());
  CPATH_CHECK_EQ(first.canonical_bytes, third.canonical_bytes);
}

CPATH_TEST(UnitRequest, binding_change_changes_the_digest) {
  ct::SyntheticParams params;
  params.participants = 6;
  params.spine_count = 2;
  params.rack_count = 3;
  const cp::RequestSpec base = ct::make_ring_spec(params);  // SYNTHETIC fabric

  cp::RequestSpec changed = base;
  CPATH_REQUIRE(!changed.bindings.empty());
  CPATH_REQUIRE_EQ(changed.bindings[0].participant.value(), std::string("p0"));
  CPATH_REQUIRE_EQ(changed.bindings[0].node.value(), std::string("n0"));
  changed.bindings[0].node = cp::NodeId{std::string("n1")};

  const cp::PlanningRequest& original = require_value(cp::build_request(base), "original request");
  const cp::PlanningRequest& rebound = require_value(cp::build_request(changed), "rebound request");
  CPATH_CHECK(original.canonical_digest != rebound.canonical_digest);
  CPATH_CHECK(original.canonical_digest.hex() != rebound.canonical_digest.hex());
  CPATH_REQUIRE(rebound.find_binding(cp::ParticipantId{std::string("p0")}) != nullptr);
  CPATH_CHECK_EQ(rebound.find_binding(cp::ParticipantId{std::string("p0")})->node.value(), std::string("n1"));
  CPATH_CHECK(rebound.find_binding(cp::ParticipantId{std::string("p9")}) == nullptr);

  // A binding for a participant the collective does not declare is refused.
  cp::RequestSpec foreign = base;
  cp::EndpointBinding extra;
  extra.participant = cp::ParticipantId{std::string("p9")};
  extra.node = cp::NodeId{std::string("n0")};
  foreign.bindings.push_back(extra);
  check_rejected(cp::build_request(foreign), cp::ErrorCode::kUnknownReference, "binding outside the collective");

  // Two bindings for one participant are refused rather than silently merged.
  cp::RequestSpec doubled = base;
  doubled.bindings.push_back(doubled.bindings[0]);
  check_rejected(cp::build_request(doubled), cp::ErrorCode::kDuplicateBinding, "duplicate binding");
}

CPATH_TEST(UnitRequest, plan_generation_is_not_part_of_the_digest) {
  ct::SyntheticParams params;
  params.participants = 6;
  params.spine_count = 2;
  params.rack_count = 3;
  cp::RequestSpec low = ct::make_ring_spec(params);  // SYNTHETIC fabric
  low.plan_generation = cp::CollectivePlanGeneration{1};
  cp::RequestSpec high = low;
  high.plan_generation = cp::CollectivePlanGeneration{2};

  const cp::PlanningRequest& first = require_value(cp::build_request(low), "plan generation 1");
  const cp::PlanningRequest& second = require_value(cp::build_request(high), "plan generation 2");

  // Documented design decision (request.hpp): the canonical digest excludes the
  // plan generation, which is a caller-supplied sequencing label rather than an
  // input to the mapping. The plan binds it separately.
  CPATH_CHECK_EQ(first.canonical_digest.hex(), second.canonical_digest.hex());
  CPATH_CHECK_EQ(first.canonical_bytes, second.canonical_bytes);

  const cp::PlanningOutcome first_outcome = cp::plan_collective(first);
  const cp::PlanningOutcome second_outcome = cp::plan_collective(second);
  CPATH_REQUIRE(first_outcome.ok());
  CPATH_REQUIRE(second_outcome.ok());
  const cp::Plan& first_plan = *first_outcome.plan;
  const cp::Plan& second_plan = *second_outcome.plan;

  // ... yet the plans bind the generation they were produced under, and that
  // binding is what a caller revalidates against.
  CPATH_CHECK_EQ(first_plan.generation.value(), std::uint64_t{1u});
  CPATH_CHECK_EQ(second_plan.generation.value(), std::uint64_t{2u});
  CPATH_CHECK_EQ(first_plan.bindings.plan.value(), std::uint64_t{1u});
  CPATH_CHECK_EQ(second_plan.bindings.plan.value(), std::uint64_t{2u});
  CPATH_CHECK(first_plan.bindings != second_plan.bindings);
  CPATH_CHECK(first_plan.id == second_plan.id);
  CPATH_CHECK_EQ(first_plan.id.value().hex(), second_plan.id.value().hex());
  CPATH_CHECK(!(first_plan.encode() == second_plan.encode()));
  CPATH_CHECK(cp::validate_plan(first_plan, first).is_ok());
  CPATH_CHECK(cp::validate_plan(second_plan, second).is_ok());
  check_rejected(cp::validate_plan(first_plan, second), cp::ErrorCode::kStalePlanGeneration,
                 "plan validated against a newer plan generation");
}

CPATH_TEST(UnitRequest, policy_generation_is_part_of_the_digest) {
  ct::SyntheticParams params;
  params.participants = 6;
  params.spine_count = 2;
  params.rack_count = 3;
  cp::RequestSpec low = ct::make_ring_spec(params);  // SYNTHETIC fabric
  low.policy.generation = cp::PolicyGeneration{5};
  cp::RequestSpec high = low;
  high.policy.generation = cp::PolicyGeneration{9};

  const cp::PlanningRequest& first = require_value(cp::build_request(low), "policy generation 5");
  const cp::PlanningRequest& second = require_value(cp::build_request(high), "policy generation 9");

  // The policy generation fences the policy content, and the policy content is
  // a mapping input, so it is inside the canonical digest.
  CPATH_CHECK(first.canonical_digest != second.canonical_digest);
  CPATH_CHECK_EQ(first.current_bindings().policy.value(), std::uint64_t{5u});
  CPATH_CHECK_EQ(second.current_bindings().policy.value(), std::uint64_t{9u});

  const cp::PlanningOutcome outcome = cp::plan_collective(second);
  CPATH_REQUIRE(outcome.ok());
  CPATH_CHECK_EQ(outcome.plan->bindings.policy.value(), std::uint64_t{9u});
  CPATH_CHECK_EQ(outcome.plan->input_digest.hex(), second.canonical_digest.hex());
  // Because the policy generation is inside the digest, a plan produced under a
  // different one no longer matches the request at the strictest check.
  check_rejected(cp::validate_plan(*outcome.plan, first), cp::ErrorCode::kPlanInputMismatch,
                 "plan validated against a different policy generation");
}

