CPATH_TEST(UnitDsl, fixture_texts_parse_with_the_declared_values) {
  const cp::PlanningRequest& minimal =
      require_value(cp::parse_request_text(ct::minimal_ring_text()), "minimal_ring_text");
  CPATH_CHECK_EQ(minimal.collective.id.value(), std::string("c0"));
  CPATH_CHECK_EQ(minimal.collective.logical_edges.size(), std::size_t{2});
  CPATH_CHECK_EQ(minimal.collective.participants.size(), std::size_t{2});
  CPATH_CHECK_EQ(minimal.fabric.node_count(), std::size_t{2});
  CPATH_CHECK_EQ(minimal.fabric.edge_count(), std::size_t{2});
  CPATH_CHECK_EQ(minimal.bindings.size(), std::size_t{2});
  CPATH_CHECK_EQ(minimal.policy.max_hops, std::size_t{4});
  CPATH_CHECK_EQ(minimal.policy.paths_per_logical_edge, std::size_t{1});
  CPATH_CHECK_EQ(minimal.plan_generation.value(), std::uint64_t{1u});
  CPATH_CHECK_EQ(minimal.current_bindings().topology.value(), std::uint64_t{7u});
  CPATH_CHECK_EQ(minimal.current_bindings().failure_domains.value(), std::uint64_t{3u});
  CPATH_CHECK_EQ(minimal.current_bindings().capacity_evidence.value(), std::uint64_t{11u});
  CPATH_CHECK(minimal.validate().is_ok());

  const cp::PlanningRequest& four =
      require_value(cp::parse_request_text(ct::four_node_ring_text()), "four_node_ring_text");
  CPATH_CHECK_EQ(four.collective.logical_edges.size(), std::size_t{4});
  CPATH_CHECK_EQ(four.collective.demand_mbps, std::uint64_t{1000u});
  CPATH_CHECK_EQ(four.policy.paths_per_logical_edge, std::size_t{2});
  CPATH_CHECK_EQ(four.policy.max_hops, std::size_t{6});
  CPATH_CHECK_EQ(std::string(cp::to_string(four.policy.disjointness)), std::string("edge"));
  CPATH_CHECK_EQ(std::string(cp::to_string(four.policy.domain_diversity)), std::string("required"));
  CPATH_CHECK_EQ(std::string(cp::to_string(four.policy.domain_diversity_level)), std::string("rack"));
  // Declared by the shipped fixture text: four leaves, two spines, sixteen
  // directed links, three failure domains and four endpoint bindings.
  CPATH_CHECK_EQ(four.fabric.node_count(), std::size_t{6});
  CPATH_CHECK_EQ(four.fabric.edge_count(), std::size_t{16});
  CPATH_CHECK_EQ(four.fabric.failure_domains().size(), std::size_t{3});
  CPATH_CHECK_EQ(four.bindings.size(), std::size_t{4});
  CPATH_CHECK(four.validate().is_ok());
  for (const cp::EndpointBinding& binding : four.bindings) {
    CPATH_CHECK(four.fabric.find_node(binding.node) != nullptr);
    CPATH_CHECK(std::find(four.collective.participants.begin(), four.collective.participants.end(),
                          binding.participant) != four.collective.participants.end());
  }
  for (const cp::Edge& edge : four.fabric.edges()) {
    CPATH_CHECK(four.fabric.find_node(edge.from) != nullptr);
    CPATH_CHECK(four.fabric.find_node(edge.to) != nullptr);
  }
}

CPATH_TEST(UnitDsl, encoded_requests_round_trip_to_the_same_digest) {
  const std::vector<std::string> texts = {ct::minimal_ring_text(), ct::four_node_ring_text()};
  for (const std::string& text : texts) {
    const cp::PlanningRequest& parsed = require_value(cp::parse_request_text(text), "fixture request");
    const std::string rendered = cp::encode_request_text(parsed);
    CPATH_CHECK(rendered.find("cpath-request 1") == 0u);
    const cp::PlanningRequest& again = require_value(cp::parse_request_text(rendered), "re-parsed request");
    CPATH_CHECK_EQ(again.canonical_digest.hex(), parsed.canonical_digest.hex());
    CPATH_CHECK_EQ(again.canonical_bytes, parsed.canonical_bytes);
    CPATH_CHECK_EQ(cp::encode_request_text(again), rendered);
    // The re-parse rebuilds the same model, not merely the same digest.
    CPATH_CHECK(again.collective.logical_edges.size() == parsed.collective.logical_edges.size());
    CPATH_CHECK(again.fabric.edges().size() == parsed.fabric.edges().size());
    CPATH_CHECK(again.bindings.size() == parsed.bindings.size());
  }
}

CPATH_TEST(UnitDsl, reader_rejections_use_exact_codes) {
  const std::string minimal = ct::minimal_ring_text();
  std::vector<RejectionCase> cases;
  cases.push_back({"missing banner", cp::ErrorCode::kMissingRequiredField, "plan-generation 1\n"});
  cases.push_back({"wrong banner version", cp::ErrorCode::kUnsupportedFormatVersion, "cpath-request 2\n"});
  cases.push_back({"unknown section", cp::ErrorCode::kUnknownKeyword, minimal + "\n[bogus]\n"});
  cases.push_back({"unknown key", cp::ErrorCode::kUnknownKeyword, minimal + "bogus=1\n"});
  cases.push_back({"duplicate section", cp::ErrorCode::kDuplicateIdentifier, minimal + "\n[policy]\n"});
  cases.push_back({"duplicate node", cp::ErrorCode::kDuplicateIdentifier,
                   insert_after_section(minimal, "nodes", "n0 site=S0 rack=R0 host=HX device=0 tier=LEAF")});
  cases.push_back({"missing required key", cp::ErrorCode::kMissingRequiredField,
                   insert_after_section(minimal, "edges", "e9 from=n0 capacity=1000")});
  cases.push_back({"non numeric number", cp::ErrorCode::kMalformedNumber,
                   replace_first(minimal, "plan-generation 1", "plan-generation abc")});
  cases.push_back({"leading zero number", cp::ErrorCode::kMalformedNumber,
                   replace_first(minimal, "plan-generation 1", "plan-generation 01")});
  cases.push_back({"out of range number", cp::ErrorCode::kValueOutOfRange,
                   replace_first(minimal, "plan-generation 1", "plan-generation 18446744073709551616")});
  cases.push_back({"line too long", cp::ErrorCode::kLineTooLong, minimal + "#" + std::string(4096u, 'x') + "\n"});
  cases.push_back({"assignment without equals", cp::ErrorCode::kInvalidSyntax, minimal + "max-hops\n"});
  cases.push_back({"repeated key on one line", cp::ErrorCode::kDuplicateIdentifier,
                   minimal + "max-hops=8 max-hops=9\n"});

  // The spliced texts must still differ from the original, otherwise a case
  // would silently assert the wrong thing.
  for (const RejectionCase& item : cases) {
    CPATH_CHECK(!item.text.empty());
    check_rejection_case(item);
  }
  // The unmodified fixture remains acceptable, so the cases above prove
  // rejection rather than general breakage.
  CPATH_CHECK(cp::parse_request_text(minimal).has_value());
}

// ===========================================================================
// Freshness
// ===========================================================================

CPATH_TEST(UnitFreshness, each_generation_field_has_its_own_freshness) {
  const cp::GenerationBindings current = sample_bindings();
  const cp::Plan plan = plan_with_bindings(current);
  CPATH_CHECK_EQ(std::string(cp::to_string(cp::assess_freshness(plan, current))), std::string("current"));

  cp::GenerationBindings changed = current;
  changed.topology = cp::TopologyGeneration{8};
  CPATH_CHECK_EQ(std::string(cp::to_string(cp::assess_freshness(plan, changed))), std::string("stale-topology"));

  changed = current;
  changed.failure_domains = cp::FailureDomainGeneration{4};
  CPATH_CHECK_EQ(std::string(cp::to_string(cp::assess_freshness(plan, changed))),
                 std::string("stale-failure-domains"));

  changed = current;
  changed.capacity_evidence = cp::CapacityEvidenceGeneration{12};
  CPATH_CHECK_EQ(std::string(cp::to_string(cp::assess_freshness(plan, changed))),
                 std::string("stale-capacity-evidence"));

  changed = current;
  changed.policy = cp::PolicyGeneration{6};
  CPATH_CHECK_EQ(std::string(cp::to_string(cp::assess_freshness(plan, changed))), std::string("stale-policy"));

  changed = current;
  changed.plan = cp::CollectivePlanGeneration{2};
  CPATH_CHECK_EQ(std::string(cp::to_string(cp::assess_freshness(plan, changed))),
                 std::string("stale-plan-generation"));

  // The classification is ordered: topology wins over every later fence.
  changed = current;
  changed.topology = cp::TopologyGeneration{8};
  changed.policy = cp::PolicyGeneration{6};
  CPATH_CHECK_EQ(std::string(cp::to_string(cp::assess_freshness(plan, changed))), std::string("stale-topology"));

  // A plan produced from a real request is current against that request.
  ct::SyntheticParams params;
  params.participants = 6;
  params.spine_count = 2;
  params.rack_count = 3;
  const cp::PlanningRequest& request =
      require_value(cp::build_request(ct::make_ring_spec(params)), "synthetic request");
  const cp::PlanningOutcome outcome = cp::plan_collective(request);
  CPATH_REQUIRE(outcome.ok());
  CPATH_CHECK_EQ(std::string(cp::to_string(cp::assess_freshness(*outcome.plan, request.current_bindings()))),
                 std::string("current"));
}

CPATH_TEST(UnitFreshness, describe_freshness_maps_to_error_codes) {
  const std::vector<std::pair<cp::PlanFreshness, cp::ErrorCode>> expected = {
      {cp::PlanFreshness::kCurrent, cp::ErrorCode::kOk},
      {cp::PlanFreshness::kStaleTopology, cp::ErrorCode::kStaleTopologyGeneration},
      {cp::PlanFreshness::kStaleFailureDomains, cp::ErrorCode::kStaleFailureDomainGeneration},
      {cp::PlanFreshness::kStaleCapacityEvidence, cp::ErrorCode::kStaleCapacityEvidenceGeneration},
      {cp::PlanFreshness::kStalePolicy, cp::ErrorCode::kStalePolicyGeneration},
      {cp::PlanFreshness::kStalePlanGeneration, cp::ErrorCode::kStalePlanGeneration},
      {cp::PlanFreshness::kUnverified, cp::ErrorCode::kRevalidationRequired},
  };
  for (const auto& [freshness, code] : expected) {
    cp::ErrorCode observed = cp::ErrorCode::kInternalError;
    const char* description = cp::describe_freshness(freshness, observed);
    CPATH_CHECK(observed == code);
    CPATH_REQUIRE(description != nullptr);
    CPATH_CHECK(std::string(description).size() > 0u);
    CPATH_CHECK_EQ(std::string(cp::to_string(freshness)).empty(), false);
  }
  // Only kCurrent maps to success.
  cp::ErrorCode code = cp::ErrorCode::kInternalError;
  (void)cp::describe_freshness(cp::PlanFreshness::kCurrent, code);
  CPATH_CHECK(code == cp::ErrorCode::kOk);
}

// ===========================================================================
// Plan comparison
// ===========================================================================

CPATH_TEST(UnitCompare, identical_plans_compare_identical) {
  const cp::RequestSpec spec = diamond_request(10u, 100u);  // SYNTHETIC diamond
  const cp::PlanningRequest& request = require_value(cp::build_request(spec), "diamond request");
  const cp::PlanningOutcome first = cp::plan_collective(request);
  const cp::PlanningOutcome second = cp::plan_collective(request);
  CPATH_REQUIRE(first.ok());
  CPATH_REQUIRE(second.ok());
  CPATH_CHECK(first.plan->encode() == second.plan->encode());

  const cp::PlanComparison comparison = cp::compare_plans(*first.plan, *second.plan);
  CPATH_CHECK(comparison.identical);
  CPATH_CHECK(comparison.same_input_digest);
  CPATH_CHECK(comparison.same_collective);
  CPATH_CHECK(!comparison.left_is_replan_of_right);
  CPATH_CHECK_EQ(comparison.changed_logical_edges, std::size_t{0});
  CPATH_CHECK_EQ(comparison.added_paths, std::size_t{0});
  CPATH_CHECK_EQ(comparison.removed_paths, std::size_t{0});
  CPATH_CHECK_EQ(comparison.rewritten_paths, std::size_t{0});
  CPATH_CHECK_EQ(comparison.summary, std::string("plans are byte-identical"));
}

CPATH_TEST(UnitCompare, topology_change_reports_the_changed_logical_edge) {
  // Same collective and bindings, different physical latency: the mapping must
  // move to the other route while the collective identity stays the same.
  const cp::PlanningRequest& original =
      require_value(cp::build_request(diamond_request(10u, 100u)), "fast route first");  // SYNTHETIC
  const cp::PlanningRequest& replanned =
      require_value(cp::build_request(diamond_request(200u, 5u)), "fast route second");  // SYNTHETIC
  const cp::PlanningOutcome before = cp::plan_collective(original);
  const cp::PlanningOutcome after = cp::plan_collective(replanned);
  CPATH_REQUIRE(before.ok());
  CPATH_REQUIRE(after.ok());
  CPATH_REQUIRE_EQ(before.plan->paths.size(), std::size_t{1});
  CPATH_REQUIRE_EQ(after.plan->paths.size(), std::size_t{1});
  CPATH_CHECK_EQ(before.plan->paths[0].hops[0].edge.value(), std::string("e0"));
  CPATH_CHECK_EQ(after.plan->paths[0].hops[0].edge.value(), std::string("e2"));

  const cp::PlanComparison comparison = cp::compare_plans(*after.plan, *before.plan);
  CPATH_CHECK(!comparison.identical);
  CPATH_CHECK(!comparison.same_input_digest);
  CPATH_CHECK(comparison.same_collective);
  CPATH_CHECK_EQ(comparison.changed_logical_edges, std::size_t{1});
  CPATH_CHECK_EQ(comparison.rewritten_paths, std::size_t{1});
  CPATH_CHECK_EQ(comparison.added_paths, std::size_t{0});
  CPATH_CHECK_EQ(comparison.removed_paths, std::size_t{0});
  CPATH_REQUIRE_EQ(comparison.differences.size(), std::size_t{1});
  CPATH_CHECK_EQ(comparison.differences[0].logical_edge.value(), std::uint64_t{1u});
  CPATH_CHECK(comparison.differences[0].left_present);
  CPATH_CHECK(comparison.differences[0].right_present);
  CPATH_CHECK(!comparison.differences[0].identical);
  CPATH_CHECK(comparison.differences[0].summary.find("rewritten") != std::string::npos);
  CPATH_CHECK(comparison.summary.find("1 logical edge(s) changed") != std::string::npos);
}

int main(int argc, char** argv) { return cpath_test::Registry::instance().run(argc, argv); }
